/// \input  CddStp_Simulation_HandleStatusRegisters_Param3 = 1u;
/// \input  CddStp_Simulation_HandleStatusRegisters_Param4 = 1u;
/// \input  CddStp_Simulation_Data.ulSimActivated = CDDSTP_SIMULATION_PASSWORD;
/// \input  CddStp_Simulation_Data.ucSim_StReg_Basic = 0u;
/// \input  CddStp_Simulation_Data.ucSim_StReg_Fault = 0u;
/// \input  CddStp_Simulation_Data.ucSim_StReg_DiagStatus1 = 0u;
/// \input  CddStp_Simulation_Data.ucSim_StReg_DiagStatus2 = 0u;
///
///   - Expectations:
///
/// \output CddStp_Simulation_Data.ucSim_StReg_Basic = CddStp_Simulation_HandleStatusRegisters_Param1
/// \output CddStp_Simulation_Data.ucSim_StReg_Fault = CddStp_Simulation_HandleStatusRegisters_Param2
